/* oxlint-disable jsx-a11y/no-autofocus */
import { Box, Divider, SidePanel } from '@wix/design-system';
import React, { useContext } from 'react';

import { RicosContext } from './../../../ricos-context/index.js';
import { Panel, PanelHeader } from './../../../ui-components/index.js';

import { MODAL_ROOT } from '../data-hooks/data-hooks.js';
import { AttributesMobile } from './attributes/attributes-mobile.js';
import { Footer } from './footer.js';
import { SectionMobile } from './section/section-mobile.js';
import { TypeSelect } from './type-select.js';
import type { LinkModalProps } from './types.js';
import { useLinkModalState } from './use-link-modal-state.js';
import { WebAddress } from './web-address.js';

export const ModalMobile: React.FC<LinkModalProps> = ({
  initialValue,
  enabledLinkTypes: enabledLinkTypesProp,
  onClose,
  onSave,
  onUnlink,
}) => {
  const { t } = useContext(RicosContext);

  const {
    link,
    linkType,
    submitError,
    enabledLinkTypes,

    onChangeAttributes,
    onChangeWebAddress,
    onClickUnlink,
    onSelectSection,
    onSelectType,
    onSubmit,
    onValidateWebAddress,
  } = useLinkModalState({
    initialValue,
    onClose,
    onSave,
    onUnlink,
    enabledLinkTypes: enabledLinkTypesProp,
  });

  return (
    <Panel
      dataHook={MODAL_ROOT}
      closeButtonProps={{ onClick: onClose }}
      skin="floating"
      width="100%"
    >
      <PanelHeader title={t('LinkSettings_Modal_Title')} />
      <SidePanel.Content noPadding>
        <Box boxSizing="border-box" direction="vertical" gap="SP3" height="100%" padding={0}>
          <Box padding="SP3" paddingBottom={0}>
            {enabledLinkTypes && enabledLinkTypes.length === 1 ? null : (
              <TypeSelect
                autoFocus={false}
                onSelect={onSelectType}
                showSitePages={false}
                t={t}
                type={linkType}
                enabledLinkTypes={enabledLinkTypes}
              />
            )}
          </Box>
          {linkType === 'section' ? (
            <SectionMobile link={link} onSelect={onSelectSection} t={t} />
          ) : (
            <>
              <Box direction="vertical" paddingLeft="SP3" paddingRight="SP3">
                <WebAddress
                  autoFocus
                  link={link}
                  onChangeUrl={onChangeWebAddress}
                  onValidateUrl={onValidateWebAddress}
                  submitError={submitError}
                  t={t}
                />
              </Box>
              <Divider />
              <Box direction="vertical" padding="SP3">
                <AttributesMobile link={link} onChange={onChangeAttributes} t={t} />
              </Box>
            </>
          )}
        </Box>
      </SidePanel.Content>
      <SidePanel.Footer showDivider>
        <Footer
          onClickCancel={onClose}
          onClickSave={onSubmit}
          onClickUnlink={onClickUnlink}
          showUnlink={Boolean(initialValue?.url || initialValue?.anchor)}
          t={t}
        />
      </SidePanel.Footer>
    </Panel>
  );
};
