/* oxlint-disable jsx-a11y/no-autofocus */
import type { PopoverProps } from '@wix/design-system';
import { Box, Divider, SidePanel } from '@wix/design-system';
import React, { useContext, useEffect, useMemo, useState } from 'react';

import { RicosContext, ZIndexContext } from './../../../ricos-context/index.js';
import { SitePagesFetchContext } from './../../site-pages/site-pages-fetch-context.js';
import { unreachable } from './../../uncreachable.js';
import { Panel, PanelHeader } from './../../../ui-components/index.js';

import { MODAL_ROOT } from '../data-hooks/data-hooks.js';
import { AttributesDesktop } from './attributes/attributes-desktop.js';
import { Footer } from './footer.js';
import { NotPublishedWarning } from './not-published-warning.js';
import { SectionDesktop } from './section/section-desktop.js';
import { SitePages } from './site-pages/site-pages.js';
import { TypeSelect } from './type-select.js';
import type { LinkModalProps } from './types.js';
import { useLinkModalState } from './use-link-modal-state.js';
import { WebAddress } from './web-address.js';

export const ModalDesktop: React.FC<LinkModalProps> = ({
  initialValue,
  enabledLinkTypes: enabledLinkTypesProp,
  onClose,
  onSave,
  onUnlink,
  onSaveMultiple,
}) => {
  const { environment, t } = useContext(RicosContext);
  const { expireCache, preload, sitePublished, cache } = useContext(SitePagesFetchContext);
  const zIndexService = useContext(ZIndexContext);

  const [containerRef, setContainerRef] = useState<HTMLDivElement | null>(null);
  const {
    focusTarget,
    link,
    linkType,
    submitError,
    multipleSections,
    enabledLinkTypes,

    onChangeAttributes,
    onChangeWebAddress,
    onClickUnlink,
    onSelectPage,
    onSelectSection,
    setMultipleSections,
    onSelectType,
    onSubmit,
    onValidateWebAddress,
  } = useLinkModalState({
    initialValue,
    onClose,
    onSave,
    onUnlink,
    onSaveMultiple,
    enabledLinkTypes: enabledLinkTypesProp,
  });

  const autoCompletePopoverProps: PopoverProps = useMemo(
    () => ({
      appendTo: el => el === containerRef,
      placement: 'bottom-start',
      zIndex: zIndexService.getZIndex('DRAWER'),
      maxWidth: '252px',
    }),
    [containerRef, zIndexService]
  );

  const dropDownPopoverProps: PopoverProps = useMemo(
    () => ({
      appendTo: el => el === containerRef,
      maxWidth: '252px',
      zIndex: zIndexService.getZIndex('DRAWER'),
    }),
    [containerRef, zIndexService]
  );
  const tooltipProps = useMemo(
    () => ({
      appendTo: containerRef || undefined,
      flip: true,
      zIndex: zIndexService.getZIndex('TOOLTIP'),
    }),
    [containerRef, zIndexService]
  );

  const showNotPublishedWarning =
    linkType !== 'section' && linkType !== 'web-address' && sitePublished === false;
  const showSitePages = environment === 'businessManager';

  useEffect(() => {
    if (showSitePages) {
      preload();
      return expireCache;
    }
  }, []);

  return (
    <div data-hook={MODAL_ROOT} ref={setContainerRef}>
      <Panel maxHeight={576} closeButtonProps={{ onClick: onClose }}>
        <PanelHeader title={t('LinkSettings_Modal_Title')} />
        <SidePanel.Content noPadding>
          <form onSubmit={onSubmit}>
            <input type="submit" style={{ display: 'none' }} />
            <Box direction="vertical" gap="SP2" padding="SP3">
              {enabledLinkTypes && enabledLinkTypes.length === 1 ? null : (
                <TypeSelect
                  autoFocus={focusTarget === 'type-select'}
                  dropDownPopoverProps={dropDownPopoverProps}
                  onSelect={onSelectType}
                  showSitePages={showSitePages}
                  t={t}
                  type={linkType}
                  enabledLinkTypes={enabledLinkTypes}
                  cache={cache}
                />
              )}

              {showNotPublishedWarning && <NotPublishedWarning />}
              {(() => {
                switch (linkType) {
                  case 'web-address':
                    return (
                      <WebAddress
                        autoFocus={focusTarget === 'input'}
                        key={linkType}
                        link={link}
                        onChangeUrl={onChangeWebAddress}
                        onValidateUrl={onValidateWebAddress}
                        submitError={submitError}
                        t={t}
                      />
                    );
                  case 'section':
                    return (
                      <SectionDesktop
                        autoCompletePopoverProps={autoCompletePopoverProps}
                        autoFocus={focusTarget === 'input'}
                        dropDownPopoverProps={dropDownPopoverProps}
                        key={linkType}
                        link={link}
                        onSelect={onSelectSection}
                        setMultipleSections={setMultipleSections}
                        onSubmit={onSubmit}
                        t={t}
                        tooltipProps={tooltipProps}
                        multipleSections={multipleSections}
                      />
                    );
                  case 'blogPost':
                  case 'staticPage':
                  case 'dynamicPage':
                  case 'storeProduct':
                  case 'storeCatalog':
                    return (
                      <SitePages
                        autoCompletePopoverProps={autoCompletePopoverProps}
                        autoFocus={focusTarget === 'input'}
                        key={linkType}
                        link={link}
                        linkType={linkType}
                        onSelect={onSelectPage}
                        onSubmit={onSubmit}
                        tooltipProps={tooltipProps}
                        t={t}
                      />
                    );

                  default:
                    unreachable(linkType);
                }
              })()}

              {linkType !== 'section' && (
                <>
                  <Divider />
                  <AttributesDesktop
                    link={link}
                    onChange={onChangeAttributes}
                    t={t}
                    tooltipProps={tooltipProps}
                  />
                </>
              )}
            </Box>
          </form>
        </SidePanel.Content>
        <SidePanel.Footer showDivider>
          <Footer
            onClickCancel={onClose}
            onClickSave={onSubmit}
            onClickUnlink={onClickUnlink}
            showUnlink={Boolean(initialValue?.url || initialValue?.anchor)}
            t={t}
          />
        </SidePanel.Footer>
      </Panel>
    </div>
  );
};
