import { Avatar, Image as ImageBase, listItemSelectBuilder } from '@wix/design-system';
import React, { useContext, useMemo } from 'react';

import {
  ContentQueryContext,
  getAnchorableNodesQuery,
  isAnchorableNode,
} from './../../../../ricos-content-query/index.js';
import type { AnchorableNodes } from './../../../../ricos-content-query/types.js';
import { getText } from './../../../../ricos-content/lib/content-application.js';
import { EditorContext, RicosContext } from './../../../../ricos-context/index.js';
import { type FileSource, type Node, Node_Type } from './../../../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { TFunction } from './../../../../ricos-types/index.js';
import { unreachable } from './../../../uncreachable.js';
import { getImageSrc } from './../../../../wix-rich-content-common/lib/image-utils.js';
import { ShapeViewRenderer } from './../../../../plugin-shape/viewer/viewer-shape.js';

import { containsUrl } from '../../../link/contains-url.js';
import { sectionTypeKeys } from '../../section-type-keys.js';
import { BlockQuoteIcon } from './icons/block-quote-icon.js';
import { ButtonIcon } from './icons/button-icon.js';
import { CodeBlockIcon } from './icons/code-block-icon.js';
import { FileIcon } from './icons/file-icon.js';
import { GalleryIcon } from './icons/gallery-icon.js';
import { GiphyIcon } from './icons/giphy-icon.js';
import { H1Icon } from './icons/h1-icon.js';
import { H2Icon } from './icons/h2-icon.js';
import { H3Icon } from './icons/h3-icon.js';
import { H4Icon } from './icons/h4-icon.js';
import { H5Icon } from './icons/h5-icon.js';
import { H6Icon } from './icons/h6-icon.js';
import { ImageIcon } from './icons/image-icon.js';
import { ParagraphIcon } from './icons/paragraph-icon.js';
import { VideoIcon } from './icons/video-icon.js';

type AnchorableNode = Node & { type: AnchorableNodes };

export type Section = {
  id: string;
  node: Node;
  prefix: React.ReactNode;
  prefixAvatar: React.ReactNode;
  subtitle: string;
  title: string;
};

const headingIcons: Record<string, React.ReactNode> = {
  1: <H1Icon />,
  2: <H2Icon />,
  3: <H3Icon />,
  4: <H4Icon />,
  5: <H5Icon />,
  6: <H6Icon />,
};

const getPrefix = (node: AnchorableNode): React.ReactNode => {
  switch (node.type) {
    case Node_Type.BLOCKQUOTE:
      return <BlockQuoteIcon />;
    case Node_Type.BUTTON:
      return <ButtonIcon />;
    case Node_Type.CODE_BLOCK:
      return <CodeBlockIcon />;
    case Node_Type.FILE:
      return <FileIcon />;
    case Node_Type.GALLERY: {
      const item = node.galleryData?.items[0];
      const src =
        item && item.video
          ? item?.video?.thumbnail?.src?.url
          : (item?.image?.media?.src?.id ?? item?.image?.media?.src?.url);
      return src ? <ImagePreview src={src} /> : <GalleryIcon />;
    }
    case Node_Type.GIF: {
      const src = node.gifData?.downsized?.still;
      return src ? <ImagePreview src={src} /> : <GiphyIcon />;
    }
    case Node_Type.HEADING:
      return headingIcons[node.headingData?.level || 0];
    case Node_Type.IMAGE: {
      const src = node.imageData?.image?.src?.url ?? node.imageData?.image?.src?.id;
      return src ? <ImagePreview src={src} /> : <ImageIcon />;
    }
    case Node_Type.PARAGRAPH:
      return <ParagraphIcon />;
    case Node_Type.VIDEO: {
      const src = node.videoData?.thumbnail?.src?.url ?? node.videoData?.thumbnail?.src?.id;
      return src ? <ImagePreview src={src} /> : <VideoIcon />;
    }
    case Node_Type.SHAPE: {
      const shapeData = node.shapeData;
      return (
        <ShapePreview
          shapeSrc={shapeData?.shape?.src as FileSource}
          color={shapeData?.styles?.color as string}
        />
      );
    }
    default:
      unreachable(node.type);
  }
};

const getTitle = (node: AnchorableNode, nodeIndex: number, t: TFunction): string | undefined => {
  switch (node.type) {
    case Node_Type.BLOCKQUOTE:
      return node.nodes[0].nodes[0].textData?.text;
    case Node_Type.BUTTON:
      return node.buttonData?.text;
    case Node_Type.CODE_BLOCK:
      return node.nodes[0].textData?.text;
    case Node_Type.FILE:
      return node.fileData?.name || `${t('LinkTo_Modal_Section_Item_File')} ${nodeIndex}`;
    case Node_Type.GALLERY:
      return `${t('LinkTo_Modal_Section_Item_Gallery')} ${nodeIndex}`;
    case Node_Type.GIF:
      return `${t('LinkTo_Modal_Section_Item_GIF')} ${nodeIndex}`;
    case Node_Type.HEADING:
      return getText(node).join('');
    case Node_Type.IMAGE:
      return `${t('LinkTo_Modal_Section_Item_Image')} ${nodeIndex}`;
    case Node_Type.PARAGRAPH:
      return getText(node).join('');
    case Node_Type.VIDEO:
      return `${t('LinkTo_Modal_Section_Item_Video')} ${nodeIndex}`;
    case Node_Type.SHAPE:
      return `${t('LinkTo_Modal_Section_Item_Shape')} ${nodeIndex}`;
    default:
      unreachable(node.type);
  }
};

export const useSectionOptions = () => {
  const contentQueryService = useContext(ContentQueryContext);
  const { getPublicCommands } = useContext(EditorContext);
  const { t } = useContext(RicosContext);

  const selection = getPublicCommands().getSelection();
  const anchorableNodes: AnchorableNode[] = useMemo(() => {
    if (!contentQueryService) {
      return [];
    }
    // If this value causes problems, probably move it to openLinkModal() arguments:
    const selectedNodeIds = selection.selectedNodes.map(node => node.attrs.id);
    return getAnchorableNodesQuery(contentQueryService.getContentExtractor(), selection.startKey)
      .filter(isAnchorableNode)
      .filter(node =>
        selectedNodeIds.includes(node.id)
          ? false
          : node.type === Node_Type.BLOCKQUOTE
            ? node.nodes[0].nodes[0].textData?.text !== undefined
            : true
      );
  }, [contentQueryService, selection.endKey, selection.startKey]);

  return useMemo(() => {
    const counters: Record<AnchorableNodes, number> = {
      [Node_Type.PARAGRAPH]: 0,
      [Node_Type.HEADING]: 0,
      [Node_Type.CODE_BLOCK]: 0,
      [Node_Type.BLOCKQUOTE]: 0,
      [Node_Type.IMAGE]: 0,
      [Node_Type.GALLERY]: 0,
      [Node_Type.VIDEO]: 0,
      [Node_Type.BUTTON]: 0,
      [Node_Type.GIF]: 0,
      [Node_Type.FILE]: 0,
      [Node_Type.SHAPE]: 0,
    };
    const sections: Section[] = anchorableNodes
      .map(node => {
        counters[node.type] += 1;
        const prefix = getPrefix(node);
        const title = getTitle(node, counters[node.type], t) || '';
        return {
          id: node.id,
          node,
          prefix,
          prefixAvatar: <Avatar shape="square" size="size30" placeholder={prefix} />,
          subtitle: t(sectionTypeKeys[node.type]),
          title,
        };
      })
      .filter(section => !!section.title);
    const allLabel = t('LinkTo_Modal_Section_Filter_All');
    const sectionTypeOptions = [
      {
        ...listItemSelectBuilder({
          id: 'all',
          label: allLabel,
          size: 'small',
          title: allLabel,
        }),
        label: allLabel,
      },
      ...Object.entries(counters)
        .filter(([_, count]) => count)
        .map(([nodeType]) => {
          const label = t(sectionTypeKeys[nodeType as AnchorableNodes]);
          return {
            ...listItemSelectBuilder({
              id: nodeType,
              label,
              size: 'small',
              title: label,
            }),
            label,
          };
        }),
    ];
    return { sections, sectionTypeOptions };
  }, [anchorableNodes]);
};

const ImagePreview: React.FC<{ src: string }> = ({ src }) => {
  const imageSrc = getImageSrc(
    containsUrl(src)
      ? src
      : {
          file_name: src,
          id: src,
          width: 48,
          height: 48,
        },
    undefined,
    {
      requiredWidth: 48,
      requiredHeight: 48,
      requiredQuality: 80,
      imageType: 'highRes',
    }
  );
  return <ImageBase fit="contain" src={imageSrc} borderRadius={0} />;
};

const ShapePreview = ({ shapeSrc, color }: { shapeSrc: FileSource; color: string }) => {
  return (
    <div
      style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        padding: 4,
        width: 30,
        height: 30,
        fill: color,
      }}
    >
      <ShapeViewRenderer shapeSrc={shapeSrc} />
    </div>
  );
};
