/* oxlint-disable jsx-a11y/no-autofocus */
import type { DropdownLayoutValueOption, PopoverProps, TooltipProps } from '@wix/design-system';
import { AutoComplete, Box, FormField, Text, listItemSelectBuilder } from '@wix/design-system';
import type { SyntheticEvent } from 'react';
import React, { useContext, useEffect, useMemo, useRef, useState } from 'react';

import type { TFunction } from './../../../../ricos-types/common-types.js';
import type { LogBiFn } from './../../../bi-context-provider/bi-context-provider.js';
import { useBiNext } from './../../../bi-context-provider/bi-context-provider.js';
import { EditorBaseUrlContext } from './../../../editor-base-url/editor-base-url-context.js';
import { LINK_MODAL_ID } from './../../../link-modal/constants.js';
import type { NamedLink } from './../../../link/types.js';
import { SitePagesFetchContext } from './../../../site-pages/site-pages-fetch-context.js';
import type { SitePagesItem, SitePagesPageType } from './../../../site-pages/types.js';
import { removeBaseUrl } from './../../../url/remove-base-url.js';

import {
  DYNAMIC_ITEM_PAGE_SELECT,
  SITE_PAGES_EMPTY_STATE,
  SITE_PAGES_PAGE_SELECT,
} from '../../data-hooks/data-hooks.js';
import type { DropdownOption } from '../types.js';
import { useSitePages } from './use-site-pages.js';

type Option = DropdownOption & { page: SitePagesItem };

type Props = {
  autoCompletePopoverProps: PopoverProps;
  autoFocus: boolean;
  link: NamedLink;
  linkType: SitePagesPageType;
  onSelect: (path: string, title: string) => void;
  onSubmit: React.EventHandler<SyntheticEvent>;
  tooltipProps: Partial<TooltipProps>;
  t: TFunction;
};

export const SitePages: React.FC<Props> = ({
  autoCompletePopoverProps,
  autoFocus,
  link,
  linkType,
  onSelect,
  onSubmit,
  tooltipProps,
  t,
}) => {
  const { baseUrl } = useContext(EditorBaseUrlContext);
  const [hasSubpages, setHasSubpages] = useState<boolean>(false);
  const logBi = useBiNext({ pluginId: 'link', modalId: LINK_MODAL_ID });
  const pagesState = useSitePages(linkType);
  const { sitePublished } = useContext(SitePagesFetchContext);
  const options = useMemo<Option[]>(
    () =>
      pagesState.items
        .filter(item => sitePublished || !item.hasSubpages)
        .map(pageToOption(tooltipProps)),
    [pagesState.items, tooltipProps]
  );

  const [selectedOption, setSelectedOption] = useState<Option | null>(() => {
    const linkPath = removeBaseUrl(link.url || '', baseUrl);
    return options.find(option => option.page.path === linkPath) || null;
  });
  const [value, setValue] = useState<string>(selectedOption?.page.title || '');
  const ref = useRef<AutoComplete>(null);

  const onEnterPressed = (evt: SyntheticEvent) => {
    if (selectedOption && selectedOption.label === value && !hasSubpages) {
      onSubmit(evt);
    } else if ((evt.target as HTMLElement).getAttribute('data-hook')?.includes('option')) {
      setTimeout(() => onSubmit(evt));
    }
  };

  if (pagesState.areAllFetched && !pagesState.query && !pagesState.items.length) {
    return <EmptyState linkType={linkType} t={t} />;
  }

  return (
    <Box direction="vertical" gap="SP3">
      <SitePageDropdown
        t={t}
        linkType={linkType}
        autofocus={autoFocus}
        dataHook={SITE_PAGES_PAGE_SELECT}
        pagesState={pagesState}
        autoCompletePopoverProps={autoCompletePopoverProps}
        options={options}
        value={value}
        selectedOption={selectedOption}
        ref={ref}
        hasSubpages={hasSubpages}
        setSelectedOption={setSelectedOption}
        setValue={setValue}
        onEnterPressed={onEnterPressed}
        onSelect={onSelect}
        logBi={logBi}
        setHasSubpages={setHasSubpages}
      />

      {selectedOption && hasSubpages && (
        <ItemPagesDropdown
          prefix={selectedOption.page.path}
          autoCompletePopoverProps={autoCompletePopoverProps}
          tooltipProps={tooltipProps}
          t={t}
          onSelect={onSelect}
          onSubmit={onSubmit}
          logBi={logBi}
        />
      )}
    </Box>
  );
};

const EmptyState: React.FC<{ linkType: SitePagesPageType; t: TFunction }> = ({ linkType, t }) => {
  return (
    <Box
      dataHook={SITE_PAGES_EMPTY_STATE}
      direction="vertical"
      margin="SP4"
      gap="SP2"
      verticalAlign="middle"
      textAlign="center"
    >
      <Text size="small" weight="bold">
        {t(typeTranslations.EmptyState_Text1[linkType])}
      </Text>
      <Text size="small" weight="thin">
        {t(typeTranslations.EmptyState_Text2[linkType])}
      </Text>
    </Box>
  );
};

type ItemPagesDropdownProps = {
  prefix: string;
  autoCompletePopoverProps: PopoverProps;
  tooltipProps: Partial<TooltipProps>;
  t: TFunction;
  onSelect: (path: string, title: string) => void;
  onSubmit: React.EventHandler<SyntheticEvent>;
  logBi: LogBiFn;
};

const ItemPagesDropdown: React.FC<ItemPagesDropdownProps> = ({
  prefix,
  autoCompletePopoverProps,
  tooltipProps,
  t,
  onSelect,
  onSubmit,
  logBi,
}) => {
  const linkType = 'dynamicItemPage';
  const pagesState = useSitePages(linkType, prefix);
  const [value, setValue] = useState<string>('');
  const [selectedOption, setSelectedOption] = useState<Option | null>(null);

  const onEnterPressed = (evt: SyntheticEvent) => {
    if (selectedOption && selectedOption.label === value) {
      onSubmit(evt);
    }
  };

  const options = useMemo<Option[]>(
    () => pagesState.items.map(pageToOption(tooltipProps)),
    [pagesState.items, tooltipProps, prefix]
  );

  return (
    <SitePageDropdown
      t={t}
      linkType={'dynamicItemPage'}
      dataHook={DYNAMIC_ITEM_PAGE_SELECT}
      pagesState={pagesState}
      autoCompletePopoverProps={autoCompletePopoverProps}
      options={options}
      value={value}
      selectedOption={selectedOption}
      setSelectedOption={setSelectedOption}
      setValue={setValue}
      onEnterPressed={onEnterPressed}
      onSelect={onSelect}
      logBi={logBi}
    />
  );
};

type SitePageDropdownProps = {
  linkType: SitePagesPageType;
  autofocus?: boolean;
  dataHook: string;
  pagesState: ReturnType<typeof useSitePages>;
  autoCompletePopoverProps: PopoverProps;
  options: Option[];
  value: string;
  selectedOption: Option | null;
  ref?: React.RefObject<AutoComplete>;
  t: TFunction;
  hasSubpages?: boolean;
  setSelectedOption: (option: Option | null) => void;
  setValue: (value: string) => void;
  onEnterPressed: (evt: SyntheticEvent) => void;
  onSelect: (path: string, title: string) => void;
  logBi: LogBiFn;
  setHasSubpages?: (hasSubpages: boolean) => void;
};

const SitePageDropdown: React.FC<SitePageDropdownProps> = ({
  t,
  linkType,
  autofocus,
  dataHook,
  pagesState,
  autoCompletePopoverProps,
  options,
  value,
  selectedOption,
  ref,
  hasSubpages,
  setSelectedOption,
  setValue,
  onEnterPressed,
  onSelect,
  logBi,
  setHasSubpages,
}) => {
  const onChange = (evt: React.ChangeEvent<HTMLInputElement>) => {
    setSelectedOption(null);
    setValue(evt.target.value);
    pagesState.setQuery(evt.target.value);
    onSelect('', '');
  };

  const onBlur = () => {
    if (!selectedOption) {
      setValue('');
    }
    if (selectedOption && value !== selectedOption.label) {
      setValue(selectedOption.label || '');
    }
  };
  const onSelectOption = (option: DropdownLayoutValueOption) => {
    pagesState.setQuery('');

    setSelectedOption(option as Option);
    setValue((option as Option).page.title);
    onSelect(
      linkType === 'dynamicPage'
        ? `/${(option as Option).page.path}`
        : (option as Option).page.path,
      (option as Option).page.title
    );
    if (hasSubpages) {
      onSelect('', '');
    }
    logBi({ dataHook: SITE_PAGES_PAGE_SELECT, value: (option as Option).page.title });
  };

  useEffect(() => {
    if (autofocus) {
      ref?.current?.showOptions();
    }
  }, []);

  useEffect(() => {
    if (setHasSubpages) {
      setHasSubpages(checkForSubpages(selectedOption, linkType, pagesState.items));
    }
  }, [selectedOption, linkType, pagesState.items, setHasSubpages]);

  return (
    <FormField label={t(typeTranslations.AutoComplete_Label[linkType])} labelPlacement="top">
      <AutoComplete
        autoFocus={autofocus}
        dataHook={dataHook}
        dropdownWidth="auto"
        emptyStateMessage={
          pagesState.isLoading ? undefined : (
            <Text skin="disabled" size="small">
              {pagesState.query
                ? t('LinkSettings_SitePages_All_NoResults_Query', { query: pagesState.query })
                : t(typeTranslations.NoResults_Any[linkType])}
            </Text>
          )
        }
        focusOnSelectedOption
        minWidthPixels="252px"
        hasMore={pagesState.hasMore || pagesState.isLoading}
        infiniteScroll
        loadMore={pagesState.loadMore ? pagesState.loadMore : () => {}}
        placeholder={t(typeTranslations.AutoComplete_Placeholder[linkType])}
        popoverProps={autoCompletePopoverProps}
        size="small"
        textOverflow="ellipsis"
        options={options}
        value={value}
        onChange={onChange}
        // WDS introduced a bug where marked option must be in options array otherwise the component crashes
        markedOption={
          options.some(opt => opt.id === selectedOption?.id) ? selectedOption?.id : undefined
        }
        onOptionMarked={option => {
          setValue((option as Option)?.page?.title);
        }}
        onEnterPressed={onEnterPressed}
        selectedId={selectedOption?.id}
        status={pagesState.error ? 'error' : pagesState.isLoading ? 'loading' : undefined}
        onBlur={onBlur}
        onSelect={onSelectOption}
        ref={ref}
      />
    </FormField>
  );
};

const typeTranslations: Record<
  | 'AutoComplete_Label'
  | 'AutoComplete_Placeholder'
  | 'EmptyState_Text1'
  | 'EmptyState_Text2'
  | 'NoResults_Any',
  Record<SitePagesPageType, string>
> = {
  AutoComplete_Label: {
    blogPost: 'LinkSettings_SitePages_BlogPost_AutoComplete_Label',
    staticPage: 'LinkSettings_SitePages_StaticPage_AutoComplete_Label',
    dynamicPage: 'LinkSettings_SitePages_DynamicPage_AutoComplete_Label',
    dynamicItemPage: 'LinkSettings_SitePages_DynamicItemPage_AutoComplete_Label',
    storeProduct: 'LinkSettings_SitePages_StoreProduct_AutoComplete_Label',
    storeCatalog: 'LinkSettings_SitePages_StoreCatalog_AutoComplete_Label',
  },
  AutoComplete_Placeholder: {
    blogPost: 'LinkSettings_SitePages_BlogPost_AutoComplete_Placeholder',
    staticPage: 'LinkSettings_SitePages_StaticPage_AutoComplete_Placeholder',
    dynamicPage: 'LinkSettings_SitePages_DynamicPage_AutoComplete_Placeholder',
    dynamicItemPage: 'LinkSettings_SitePages_DynamicItemPage_AutoComplete_Placeholder',
    storeProduct: 'LinkSettings_SitePages_StoreProduct_AutoComplete_Placeholder',
    storeCatalog: 'LinkSettings_SitePages_StoreCatalog_AutoComplete_Placeholder',
  },
  EmptyState_Text1: {
    blogPost: 'LinkSettings_SitePages_BlogPost_EmptyState_Text1',
    staticPage: 'LinkSettings_SitePages_StaticPage_EmptyState_Text1',
    dynamicPage: 'LinkSettings_SitePages_DynamicPage_EmptyState_Text1',
    dynamicItemPage: 'LinkSettings_SitePages_DynamicItemPage_EmptyState_Text1',
    storeProduct: 'LinkSettings_SitePages_StoreProduct_EmptyState_Text1',
    storeCatalog: 'LinkSettings_SitePages_StoreCatalog_EmptyState_Text1',
  },
  EmptyState_Text2: {
    blogPost: 'LinkSettings_SitePages_BlogPost_EmptyState_Text2',
    staticPage: 'LinkSettings_SitePages_StaticPage_EmptyState_Text2',
    dynamicPage: 'LinkSettings_SitePages_DynamicPage_EmptyState_Text2',
    dynamicItemPage: 'LinkSettings_SitePages_DynamicItemPage_EmptyState_Text2',
    storeProduct: 'LinkSettings_SitePages_StoreProduct_EmptyState_Text2',
    storeCatalog: 'LinkSettings_SitePages_StoreCatalog_EmptyState_Text2',
  },
  NoResults_Any: {
    blogPost: 'LinkSettings_SitePages_BlogPost_NoResults_Any',
    staticPage: 'LinkSettings_SitePages_StaticPage_NoResults_Any',
    dynamicPage: 'LinkSettings_SitePages_DynamicPage_NoResults_Any',
    dynamicItemPage: 'LinkSettings_SitePages_DynamicItemPage_NoResults_Any',
    storeProduct: 'LinkSettings_SitePages_StoreProduct_NoResults_Any',
    storeCatalog: 'LinkSettings_SitePages_StoreCatalog_NoResults_Any',
  },
};

const pageToOption =
  (tooltipProps: Partial<TooltipProps>) =>
  (page: SitePagesItem): Option =>
    Object.assign(
      listItemSelectBuilder({
        ...page,
        ellipsis: true,
        titleMaxLines: 2,
        id: page.id,
        label: page.title ?? '',
        size: 'small',
        dataHook: 'option',
        subtitle: page.updatedDate?.toLocaleDateString() || page.description || undefined,
        tooltipProps: {
          ...tooltipProps,
          children: page.title,
          enterDelay: 1_000,
          placement: 'top',
        },
      }),
      {
        label: page.title ?? '',
        page,
      }
    );

const checkForSubpages = (
  selectedOption: Option | null,
  pageType: SitePagesPageType,
  items: SitePagesItem[]
) => {
  if (!selectedOption || pageType !== 'dynamicPage' || !items || items.length === 0) {
    return false;
  }
  return items.find(item => item.id === selectedOption.id)?.hasSubpages || false;
};
